import React, { useEffect, useState } from "react";
import Footer from "./Footer";
import Card from "./Card";
import Navbar from "./Navbar";
import { jwtDecode } from "jwt-decode";

function Shop({ onBuy, purchasedItems = {} }) {
  const [items, setItems] = useState([]);
  const [currentUserId, setCurrentUserId] = useState(null);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");

  useEffect(() => {
    // 1. Get ID from Token or Direct Local Storage
    const token = localStorage.getItem("token");
    const storedId = localStorage.getItem("userId"); // Fallback check

    if (token) {
      try {
        const decoded = jwtDecode(token);
        // Check every common MongoDB/Auth ID key
        const uid = String(decoded._id || decoded.id || decoded.userId || decoded.sub || "");
        if (uid) {
          setCurrentUserId(uid);
        } else if (storedId) {
          setCurrentUserId(String(storedId));
        }
      } catch (err) {
        console.error("Token decode failed", err);
        if (storedId) setCurrentUserId(String(storedId));
      }
    } else if (storedId) {
      setCurrentUserId(String(storedId));
    }

    // 2. Fetch Books
    fetch("http://localhost:5009/books")
      .then((res) => res.json())
      .then((data) => {
        setItems(data);
        // DEBUGGING: Remove this once it works!
        console.log("Logged In User ID:", currentUserId);
        if (data.length > 0) {
          console.log("First Book Seller ID:", data[0].userId || data[0].user || data[0].sellerId);
        }
      })
      .catch((err) => console.error("Fetch error", err))
      .finally(() => setLoading(false));
  }, [currentUserId]); // Re-run if ID changes

  // --- REFINED FILTER LOGIC ---
  const filteredItems = items.filter((item) => {
    // Check every possible seller field name from your DB
    const sellerId = String(item.userId || item.user || item.sellerId || item.owner || "");
    const myId = String(currentUserId || "");

    // Logic: Keep it if there is no user logged in OR if the seller is NOT me
    const isNotMine = !myId || sellerId !== myId;

    // Search check
    const matchesSearch = item.title
      .toLowerCase()
      .includes(searchTerm.toLowerCase());

    return isNotMine && matchesSearch;
  });

  if (loading) return <h1 style={{ textAlign: "center", marginTop: "50px" }}>Loading Books...</h1>;

  return (
    <>
      <Navbar />
      <div className="Body">
        
        {/* Search Bar UI */}
        <div style={{ padding: "20px", textAlign: "center" }}>
          <div style={{ position: "relative", display: "inline-block", width: "100%", maxWidth: "550px" }}>
            <input
              type="text"
              placeholder="Search for books..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              style={{
                backgroundColor: "#fbfbfb",
                padding: "16px 40px 16px 20px",
                width: "100%",
                borderRadius: "27px",
                border: "1px solid #ddd",
                outline: "none",
                fontSize: "16px",
              }}
            />
            {searchTerm && (
              <button
                onClick={() => setSearchTerm("")}
                style={{
                  position: "absolute",
                  right: "15px",
                  top: "50%",
                  transform: "translateY(-50%)",
                  background: "none",
                  border: "none",
                  color: "#999",
                  fontSize: "20px",
                  cursor: "pointer",
                  fontWeight: "bold",
                }}
              >
                ×
              </button>
            )}
          </div>
        </div>

        {/* Books Grid */}
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '20px', justifyContent: 'center', padding: "20px" }}>
          {filteredItems.length === 0 ? (
            <div className="HeadMo" style={{ textAlign: "center", width: "100%" }}>
              <h1>{searchTerm ? "No matches found!" : "No books for sale!"}</h1>
            </div>
          ) : (
            filteredItems.map((item) => {
              const itemId = String(item._id || item.id);
              const isPurchased = !!purchasedItems[itemId];

              return (
                <Card key={itemId} {...item}>
                  <button
                    onClick={() => !isPurchased && onBuy(item)}
                    disabled={isPurchased}
                    style={{
                      backgroundColor: isPurchased ? "#6c757d" : "#0d6efd",
                      color: "#fff",
                      borderRadius: "5px",
                      padding: "10px",
                      width: "140px",
                      border: "none",
                      cursor: isPurchased ? "not-allowed" : "pointer",
                      pointerEvents: isPurchased ? "none" : "auto", 
                      opacity: isPurchased ? 0.6 : 1,
                      marginTop: "10px"
                    }}
                  >
                    {isPurchased ? "In Cart" : "Add to Cart"}
                  </button>
                </Card>
              );
            })
          )}
        </div>
      </div>
      <Footer />
    </>
  );
}

export default Shop;
